begin;

alter table public.builders alter column email drop not null;
alter table public.builders add column if not exists registration_number text;
alter table public.builders add column if not exists registration_status text;
alter table public.builders add column if not exists registry_url text;
alter table public.builders add column if not exists registry_checked_at timestamptz;
alter table public.builders add column if not exists limitations text;
alter table public.builders add column if not exists contact_source text;
alter table public.builders add column if not exists coordinate_source text;
create unique index if not exists builders_registration_number_key
  on public.builders(registration_number) where registration_number is not null;

create table if not exists public.vic_postcode_centroids (
  postcode text primary key,
  latitude numeric(9,6) not null,
  longitude numeric(9,6) not null,
  source text not null default 'G-NAF locality centroid'
);
alter table public.vic_postcode_centroids enable row level security;

alter table public.notifications alter column user_id drop not null;
alter table public.notifications add column if not exists builder_id uuid references public.builders(id) on delete cascade;
create index if not exists notifications_builder_idx on public.notifications(builder_id, created_at desc);

create table if not exists public.builder_contact_queue (
  id uuid primary key default gen_random_uuid(),
  builder_id uuid not null references public.builders(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,
  activity_id uuid not null references public.project_activity(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'contacted', 'claimed', 'closed')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (builder_id, activity_id)
);
alter table public.builder_contact_queue enable row level security;
create policy builder_contact_queue_admin_read on public.builder_contact_queue
for select to authenticated using (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'administrator')
);
create policy builder_contact_queue_admin_update on public.builder_contact_queue
for update to authenticated using (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'administrator')
) with check (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'administrator')
);
grant select, update(status, updated_at) on public.builder_contact_queue to authenticated;

create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_builder_id uuid;
begin
  values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', ''))
  on conflict (id) do nothing;

  select b.id into v_builder_id
  from public.builders b
  where b.active
    and b.email is not null
    and lower(b.email) = lower(new.email)
  order by b.verified desc, b.created_at
  limit 1;

  if v_builder_id is not null then
    update public.profiles set role = 'builder', updated_at = now() where id = new.id;
    values (v_builder_id, new.id, true)
    on conflict (builder_id, user_id) do nothing;
  end if;
  return new;
end;
$$;
revoke all on function private.handle_new_user() from public;

drop function if exists public.find_matching_builders(text, text, numeric, numeric, integer);
create function public.find_matching_builders(
  p_postcode text,
  p_suburb text default null,
  p_latitude numeric default null,
  p_longitude numeric default null,
  p_limit integer default 12
)
returns table (
  builder_id uuid,
  builder_name text,
  suburb text,
  state text,
  description text,
  logo_url text,
  registration_number text,
  distance_km numeric
)
language sql
stable
security definer
set search_path = ''
as $$
  with target as (
    select
      coalesce(p_latitude, pc.latitude) as latitude,
      coalesce(p_longitude, pc.longitude) as longitude
    from (select 1) seed
    left join public.vic_postcode_centroids pc on pc.postcode = trim(p_postcode)
  ), candidates as (
    select
      b.id,
      b.name,
      b.suburb,
      b.state,
      b.description,
      b.logo_url,
      b.registration_number,
      b.postcode = trim(p_postcode) as same_postcode,
      case
        when t.latitude is not null and t.longitude is not null and b.latitude is not null and b.longitude is not null
        then round((6371 * acos(least(1, greatest(-1,
          cos(radians(t.latitude)) * cos(radians(b.latitude)) *
          cos(radians(b.longitude) - radians(t.longitude)) +
          sin(radians(t.latitude)) * sin(radians(b.latitude))
        ))))::numeric, 1)
        else null
      end as calculated_distance
    from public.builders b
    cross join target t
    where b.active
      and b.verified
      and coalesce(b.registration_status, 'Current') = 'Current'
  )
  select c.id, c.name, c.suburb, c.state, c.description, c.logo_url,
         c.registration_number, c.calculated_distance
  from candidates c
  order by c.calculated_distance nulls last, c.same_postcode desc, c.name
  limit least(greatest(coalesce(p_limit, 12), 1), 30);
$$;
revoke all on function public.find_matching_builders(text, text, numeric, numeric, integer) from public;
grant execute on function public.find_matching_builders(text, text, numeric, numeric, integer) to anon, authenticated;

create or replace function private.enqueue_activity_notifications()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.audience in ('client', 'all') then
    select p.client_id, new.project_id, new.id
    from public.projects p
    where p.id = new.project_id and p.client_id is distinct from new.actor_id;
  end if;

  if new.audience in ('builder', 'all') then
    select bu.user_id, i.builder_id, new.project_id, new.id
    from public.project_builder_invitations i
    join public.builder_users bu on bu.builder_id = i.builder_id
    where i.project_id = new.project_id
      and i.status in ('invited', 'accepted')
      and (new.builder_id is null or i.builder_id = new.builder_id)
      and bu.user_id is distinct from new.actor_id;

    select i.builder_id, new.project_id, new.id
    from public.project_builder_invitations i
    where i.project_id = new.project_id
      and i.status in ('invited', 'accepted')
      and (new.builder_id is null or i.builder_id = new.builder_id)
      and not exists (
        select 1 from public.builder_users bu where bu.builder_id = i.builder_id
      )
    on conflict (builder_id, activity_id) do nothing;
  end if;
  return new;
end;
$$;
revoke all on function private.enqueue_activity_notifications() from public;

on conflict (postcode) do update set latitude = excluded.latitude, longitude = excluded.longitude, source = excluded.source;

on conflict (registration_number) where registration_number is not null do update set
  name=excluded.name, slug=excluded.slug, email=excluded.email, phone=excluded.phone, website=excluded.website, description=excluded.description, address=excluded.address, suburb=excluded.suburb, state=excluded.state, postcode=excluded.postcode, latitude=excluded.latitude, longitude=excluded.longitude, verified=excluded.verified, active=excluded.active, registration_status=excluded.registration_status, registry_url=excluded.registry_url, registry_checked_at=excluded.registry_checked_at, limitations=excluded.limitations, contact_source=excluded.contact_source, coordinate_source=excluded.coordinate_source, updated_at=now();

commit;
